entries[269747] = { ["name"] = "Lauffeuerbombe", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchleudert eine Bombe auf das Ziel, die bei der Explosion in einem kegelförmigen Bereich (90% der Angriffskraft) Feuerschaden verursacht und Gegner mit Lauffeuer bedeckt, das ihnen im Verlauf von 6 Sek. (125.928% der Angriffskraft) Feuerschaden zufügt. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nFügt Eurem Primärziel 80% mehr Schaden zu." }
entries[269748] = { ["name"] = "Froststrahl", ["text"] = "Kanalisiert (Wirken in 5 sek.)\nKanalisiert 5 Sek. lang einen Strahl eisiger Macht auf einen Gegner, der ihm alle 1 Sek. (269.1% der Zaubermacht) Frostschaden zufügt und ihn um 60% verlangsamt. Jedes Mal, wenn 'Froststrahl' Schaden verursacht, werden der Schaden und die Verlangsamung des Effekts um 10% erhöht.\n\nErzeugt im Verlauf der Effektdauer 2 Aufladungen von 'Eisige Finger'." }
